def combination_sum(candidates, target)
    @result = []
    @target = target
    @candidates = candidates
    def dfs(i, current, total)
        if total == @target
            @result.append(current.dup())
            return
        end
        if i >= @candidates.length() || total > @target
            return
        end

        current.append(@candidates[i])
        dfs(i, current, total+@candidates[i])
        current.pop()
        dfs(i+1, current, total)
    end

    dfs(0,[],0)
    return @result
end

def combination_sum2(candidates, target)
    @candidates = candidates
    @candidates.sort!
    @result = []

    def backtrack (cur,pos,target)
        @result.append(cur.dup()) if target == 0
        return if target <=0

        prev = -1

        (pos..@candidates.length-1).each do |i|
            next if @candidates[i] == prev

            cur.append(@candidates[i])

            backtrack(cur,i+1,target-@candidates[i])

            cur.pop()

            prev = @candidates[i]

        end

    end
    backtrack([],0,target)

    return @result


end

def group_anagrams(strs)
  anagrams = Hash.new { |h, k| h[k] = [] }
  strs.each do |str|
    hash = Hash.new(0)
    str.each_char { |c| hash[c] += 1 }
    anagrams[hash] << str
  end
  anagrams.values
end

def exist(board, word)
    @rows = board.length
    @cols = board[0].length
    @board = board
    @word = word
    @path = Set.new()

    set1 = @board.flatten.to_set
    set2 = @word.split('').to_set
    return false if !(set1 >= set2)

    def dfs(r,c,i)
        return true if i == @word.length()
        return false if (r<0 || c<0 || r >= @rows || c >= @cols || @word[i] != @board[r][c] || @path.include?([r,c]))

        @path.add([r,c])

        result = (dfs(r+1,c,i+1) ||
                  dfs(r-1,c,i+1) ||
                  dfs(r,c+1,i+1) ||
                  dfs(r,c-1,i+1)
                 )

        @path.delete([r,c])

        return result
    end

    (0..@rows-1).each do |r|
        (0..@cols-1).each do |c|
            return true if dfs(r,c,0)
        end
    end

    return false

end

def subsets_with_dup(nums)
    @result = []
    @nums = nums.sort!

    def backtrack(i,subset)
        if i == @nums.length
            @result.append(subset.dup())
            return
        end

        subset.append(@nums[i])
        backtrack(i+1,subset)
        subset.pop()

        while ((i+1 < @nums.length) && (@nums[i] == @nums[i+1]))
            i +=1
        end

        backtrack(i+1,subset)
    end

    backtrack(0,[])

    return @result
end

def partition(s)
    @result = []
    @part = []
    @s = s

    def dfs(i)
        if i >= @s.length
            @result.append(@part.dup())
            return
        end
        (i..@s.length-1).each do |j|
            if is_palindrome(@s,i,j)
                @part.append(@s[i..j])
                dfs(j+1)
                @part.pop()
            end
        end
    end

    dfs(0)

    return @result
end


def is_palindrome(s,i,j)
    while i<j
        return false if s[i] != s[j]
        i +=1
        j -=1
    end
    return true
end

