def rob(nums)
  dp = Array.new(nums.size + 3) { 0 }

  nums.each_with_index do |num, i|
    dp[i + 3] = num + [dp[i + 1], dp[i]].max
  end

  [dp[-1], dp[-2]].max
end

require "rb_heap"

class KthLargest
  def initialize(k, nums)
    @k = k
    @heap = Heap.new
    nums.each { |num| @heap << num }
    @heap.pop until @heap.size <= @k
  end

  def add(val)
    @heap << val
    @heap.pop until @heap.size <= @k
    @heap.peak
  end
end

